def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, diagonal=True)
    out = g.copy()
    for o in objs:
        for (y, x) in o["cells"]:
            out[y, x] = bg
    emit(out.copy(), "Erase every shape; each will be re-placed shifted right by its own width.")
    H, W = g.shape
    for o in objs:
        y0, x0, y1, x1 = o["box"]
        w = x1 - x0 + 1
        for (y, x) in o["cells"]:
            nx = x + w
            if 0 <= nx < W:
                out[y, nx] = g[y, x]
        emit(out.copy(), f"Stamp the shape at rows {y0}-{y1}, cols {x0}-{x1} (width {w}) shifted right by {w}.")
    emit(out.copy(), "Final grid: every shape moved right by its width.")
    return out
